#!/usr/bin/env python3
"""Generate/check readonly tables for the explicit guest keyboard layout."""
import argparse,json,pathlib
R=pathlib.Path(__file__).resolve().parents[1];ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');args=ap.parse_args();profile=json.loads((R/'config/runtime/keyboard-layout.json').read_text());lines=['/* Generated by scripts/gen-keyboard-layout.py from keyboard-layout.json. */']
for key,name,count in [('base_scan_to_vk','tb_us_base',128),('e0_scan_to_vk','tb_us_e0',128),('unshifted_vk_to_char','tb_us_chars',256)]:
 values=profile[key];assert len(values)==count and all(isinstance(v,int) and 0<=v<=255 for v in values);lines+=['static const unsigned char %s[%d]={%s};'%(name,count,','.join(str(v) for v in values))]
values=profile['ascii_character_columns'];assert len(values)==256 and all(len(row)==4 and all(isinstance(v,int) and (0<=v<=255 or v==65535) for v in row) for row in values);lines+=['static const unsigned short tb_us_ascii[256][4]={'+','.join('{'+','.join(str(v) for v in row)+'}' for row in values)+'};']
assert profile['e1_scan_to_vk']=={'29':19} and profile['legacy_MapVirtualKey_types']==[0,1,2,3];source='\n'.join(lines)+'\n';target=R/'port/core/keyboard_layout_us.h'
if args.check:assert target.read_text()==source,'Regenerate keyboard-layout tables'
else:target.write_text(source)
